# -*- coding: utf-8 -*-
"""Киберимпланты, которые ты обязан купить (12 товаров мистера А-Мэйза; тип/цена/установка/ПЧ — по итоговой таблице)."""
from common import *

ARM = 'ПРАВАЯ КИБЕРРУКА (CYBERARM R)'
LEG = 'ПРАВАЯ КИБЕРНОГА (CYBERLEG R)'
INTERNAL = 'ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)'
EXTERNAL = 'ВНЕШНИЕ ИМПЛАНТЫ (EXTERNAL)'
FASHION = 'СТИЛЕВОЙ КИБЕРИМПЛАНТ (FASHIONWARE)'


def build(out):
    P = 'dlc10'
    out.pack(P, 'Киберимпланты, которые ты обязан купить', 'Cyberware You Must Buy')

    def C(name, key, cat, cost, inst, hl, info, slots=1):
        e = find(P, key, 'item')
        out.add(P, 'cyber', name, cost=cost, Install=inst, HL=hl, Category=cat, Slots=slots, Info=info, Lib=e['id'], Page=e['page'])

    C('Регулятор голода', 'НАРУЖНЫЙ', INTERNAL, 500, 'Госпиталь', '7 (2d6)',
      'Внутренний киберимплант. Управляет голодом и позволяет игнорировать его одним нажатием кнопки через биомонитор: пользователь игнорирует потерю Человечности от долгосрочных стрессовых факторов, связанных с едой (стр. 231). Голод остаётся проблемой: после 7 дней без пищи в начале каждого дня — спасбросок смерти с накапливающимся штрафом +1 за каждый дополнительный день. Требуется Биомонитор.')
    C('Киберподушка', 'НАРУЖНЫЙ', ARM, 100, 'Клиника', '0 (—)',
      'Опция киберруки. Выбрасывается из руки; с наполнителем КапсульКо моментально усыпляет. Никаких преимуществ, кроме возможности вздремнуть где угодно; несколько установок ничего не добавляют. Требуется киберрука.')
    C('Внешний видеоэкран Ню-Тек', 'НАРУЖНЫЙ', EXTERNAL, 100, 'Госпиталь', '7 (2d6)',
      'Внешний киберимплант. Гибкая сенсорная панель размером с корник под кожей превращает любую часть тела в экран, которым управляет связанный агент или щепка памяти в разъёме для щепок.')
    C('Голопроектор Палм', 'ГОЛОПРОЕКТОР', ARM, 100, 'Клиника', '2 (1d6/2 вверх)',
      'Опция киберруки. Голографический проектор в ладони; при подключении к агенту выдаёт потенциально интерактивную голограмму размером с банку содовой. Водонепроницаем, не скрывается гидрокостюмом. Можно поставить единственным имплантом в мясную руку.')
    C('Циферблат убийств', 'ЦИФЕРБЛАТ', FASHION, 100, 'Молл', '0 (—)',
      'Стилевой имплант. Светящаяся надпись под кожей «ЗАМОЧИЛ:» и число (до 999), задаваемое через связанного агента. Считается установкой «Светящихся тату»: при трёх таких установках +2 к Гардеробу и стилю (стр. 358).')
    C('Соблазнительные ноготочки «Вкл-Выкл»', 'НОГОТОЧКИ', FASHION, 100, 'Молл', '0 (—)',
      'Стилевой имплант. 10 программируемых подсвечиваемых ногтей; в комплекте световые ручки, пресеты можно загрузить из Городской СЕТи через агента. Считается установкой «Светящихся тату» (+2 к Гардеробу и стилю при трёх). Ставится в мясные и кибернетические руки.')
    C('Глаза настроения', 'ГЛАЗА НАСТРОЕНИЯ', FASHION, 100, 'Молл', '0 (—)',
      'Стилевой имплант. Линзы меняют цвет глаз по самой сильной эмоции из скана мозга через Нейролинк: красный — злоба, синий — грусть, жёлтый — страх, розовый — раздражение, зелёный — ревность, серый — смерть. Подделать скан — Актёрское мастерство СЛ21. Отключается без действия. Требуется Нейролинк.')
    C('НеоЯзык', 'НЕОЯЗЫК', INTERNAL, 100, 'Госпиталь', '7 (2d6)',
      'Внутренний киберимплант. Меняет чувство вкуса: через связанного агента к еде добавляются виртуальные приправы. Отключается без действия (тогда вкуса нет вовсе).')
    C('Идеальная киберстопа', 'ИДЕАЛЬНАЯ', LEG, 100, 'Клиника', '2 (1d6/2 вверх)',
      'Опция киберноги. Действием меняет размер стопы от 0 EU до 37AA US; гидравлический каблук. В паре сводит к нулю штрафы за плохо сидящую обувь вне ситуаций моды. Можно поставить единственным имплантом в мясную ногу.')
    C('Персональный разогреватель Киббла', 'РАЗОГРЕВАТЕЛЬ', ARM, 100, 'Клиника', '3 (1d6)',
      'Опция киберруки. Небольшая печь-вертел в предплечье под цилиндр «Персональная упаковка Киббла», разогревает его до хрустящей корочки. Требуется киберрука.')
    C('Ускоренный защищённый встроенный персональный шредер', 'ШРЕДЕР', ARM, 100, 'Клиника', '3 (1d6)',
      'Опция киберруки. Коммерческий шредер поперечной резки в киберруке с резервуаром для отходов. Требуется киберрука.')
    C('Покрытие для спонсоров', 'СПОНСОР', ARM, 50, 'Молл', '0 (—)',
      'Вариант киберконечности (не занимает слот опций; нужна киберрука или кибернога). Конечность покрыта рекламой. Пока пользователь в добрых отношениях со спонсором (не творит сомнительного, участвует в мероприятиях, показывает конечность без одежды), 1-го числа каждого месяца он получает 20eb. Часто спонсорское покрытие оплачивается заранее по контракту; известны случаи, когда спонсоры пытались отобрать всю руку при нарушении договора.', slots=0)
